-- CreateTable: CarcCode — X12 Claim Adjustment Reason Codes reference table,
-- seeded from https://x12.org/codes/claim-adjustment-reason-codes (2026-08-12 snapshot).
-- Safe to re-run: CREATE TABLE IF NOT EXISTS + ON CONFLICT DO NOTHING make every
-- statement idempotent.
CREATE TABLE IF NOT EXISTS "CarcCode" (
    "id" TEXT NOT NULL,
    "code" TEXT NOT NULL,
    "description" TEXT NOT NULL,
    "active" BOOLEAN NOT NULL DEFAULT true,
    "startDate" TIMESTAMP(3),
    "lastModified" TIMESTAMP(3),
    "stopDate" TIMESTAMP(3),
    "notes" TEXT,
    "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updatedAt" TIMESTAMP(3) NOT NULL,

    CONSTRAINT "CarcCode_pkey" PRIMARY KEY ("id")
);

DO $$ BEGIN
    ALTER TABLE "CarcCode" ADD CONSTRAINT "CarcCode_code_key" UNIQUE ("code");
EXCEPTION
    WHEN duplicate_object THEN NULL;
END $$;

CREATE INDEX IF NOT EXISTS "CarcCode_active_idx" ON "CarcCode"("active");

-- Seed data (407 codes: 297 active, 110 deactivated)
ON CONFLICT ("code") DO NOTHING;
